def maximum_value(maximum_weight, items):
    dp = [0] * (maximum_weight + 1)

    for item in items:
        item_weight = item["weight"]
        item_value = item["value"]

        for current_weight in range(maximum_weight, item_weight - 1, -1):
            dp[current_weight] = max(dp[current_weight], dp[current_weight - item_weight] + item_value)

    return dp[maximum_weight]
